# {{script_name}}.ps1, generated by API Toolbar on {{date}}.
# @if hosts
# Calls: {{hosts}}
# @end
#
# Works in Windows PowerShell 5.1 and PowerShell 7.
# Run with: powershell -ExecutionPolicy Bypass -File {{script_name}}.ps1
# Each run saves its responses to a new dated folder, one file per request.

$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName System.Net.Http
[Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12

$EnvFile = [IO.Path]::ChangeExtension($PSCommandPath, '.env')
if (Test-Path -LiteralPath $EnvFile) {
    foreach ($envLine in [IO.File]::ReadAllLines($EnvFile)) {
        if ($envLine -match '^([A-Za-z0-9_]+)=(.*)$') {
            [Environment]::SetEnvironmentVariable($Matches[1], (ConvertFrom-Json -InputObject $Matches[2]))
        }
    }
}

$OutDir = [IO.Path]::Combine((Get-Location).Path, $(if ($env:OUT_DIR) { $env:OUT_DIR } else { "./{{script_name}}_output/$(Get-Date -Format 'yyyy-MM-dd_HH-mm-ss')" }))
# @if has_loops
# Safety limits for loops, and a pause between requests to stay polite.
$MaxPages = if ($env:MAX_PAGES) { [int]$env:MAX_PAGES } else { 100 }
$MaxItems = if ($env:MAX_ITEMS) { [int]$env:MAX_ITEMS } else { 1000 }
$DelayMs = if ($env:DELAY) { [int]([double]$env:DELAY * 1000) } else { 200 }
# @end

{{settings}}

[void](New-Item -ItemType Directory -Force -Path (Join-Path $OutDir 'headers'))
[Console]::Error.WriteLine("Saving responses to $OutDir")

$Cookies = [Net.CookieContainer]::new()
$Handler = [Net.Http.HttpClientHandler]::new()
$Handler.CookieContainer = $Cookies
$Handler.AllowAutoRedirect = $false
$Handler.AutomaticDecompression = [Net.DecompressionMethods]::GZip -bor [Net.DecompressionMethods]::Deflate
$Client = [Net.Http.HttpClient]::new($Handler)
$Client.Timeout = [TimeSpan]::FromSeconds(60)

# @helper Add-BrowserCookies
# Starts the session with cookies from the browser, for one host only.
function Add-BrowserCookies {
    param([string]$Url, [string]$Text)
    $uri = [Uri]$Url
    foreach ($pair in ($Text -split ';\s*')) {
        $split = $pair.IndexOf('=')
        if ($split -le 0) { continue }
        try {
            $Cookies.Add($uri, [Net.Cookie]::new($pair.Substring(0, $split), $pair.Substring($split + 1), '/'))
        } catch {
            Write-Warning "Skipped a cookie .NET will not accept: $($pair.Substring(0, $split))"
        }
    }
}

# @end

# Sends one request, saves the response to OutDir, and returns it.
function Send-Request {
    param(
        [string]$File,
        [string]$Method,
        [string]$Url,
        $Headers = @{},
        [string]$Body,
        [switch]$AllowError
    )
    $attempts = if ($Method -eq 'GET') { 4 } else { 1 }
    for ($attempt = 1; $attempt -le $attempts; $attempt++) {
        $message = [Net.Http.HttpRequestMessage]::new([Net.Http.HttpMethod]::new($Method), $Url)
        $contentType = $null
        foreach ($header in $Headers.Keys) {
            if ($header -ieq 'content-type') { $contentType = $Headers[$header]; continue }
            [void]$message.Headers.TryAddWithoutValidation($header, [string]$Headers[$header])
        }
        if ($PSBoundParameters.ContainsKey('Body')) {
            $message.Content = [Net.Http.ByteArrayContent]::new([Text.Encoding]::UTF8.GetBytes($Body))
            if ($contentType) { [void]$message.Content.Headers.TryAddWithoutValidation('Content-Type', $contentType) }
        }
        $response = $Client.SendAsync($message).GetAwaiter().GetResult()
        $status = [int]$response.StatusCode
        if (@(429, 500, 502, 503, 504) -notcontains $status -or $attempt -eq $attempts) { break }
        Start-Sleep -Seconds $attempt
    }
    $bytes = $response.Content.ReadAsByteArrayAsync().GetAwaiter().GetResult()
    $text = [Text.Encoding]::UTF8.GetString($bytes)
    [IO.File]::WriteAllBytes((Join-Path $OutDir $File), $bytes)
    $responseHeaders = @{}
    foreach ($group in @($response.Headers, $response.Content.Headers)) {
        foreach ($entry in $group) { $responseHeaders[$entry.Key] = ($entry.Value -join ', ') }
    }
    $headerLines = $responseHeaders.GetEnumerator() | ForEach-Object { "$($_.Key): $($_.Value)" }
    [IO.File]::WriteAllLines((Join-Path $OutDir "headers/$File.txt"), [string[]]@($headerLines))
    [Console]::Error.WriteLine("$Method ${File}: HTTP $status")
    if ($status -ge 400 -and -not $AllowError) {
        # A short error message helps, but a whole web page would bury the log.
        $preview = $text.Substring(0, [Math]::Min(500, $text.Length))
        if ($preview -notmatch '<(!doctype|html)') { [Console]::Error.WriteLine($preview) }
        throw "$File failed with HTTP $status. The response is saved in $(Join-Path $OutDir $File)"
    }
    [pscustomobject]@{ Status = $status; Text = $text; Headers = $responseHeaders; Url = $Url }
}

# @helper Read-Json
function Read-Json {
    param($Response)
    ConvertFrom-Json -InputObject $Response.Text
}

# @end
# @helper Read-JsonFile
function Read-JsonFile {
    param([string]$File)
    ConvertFrom-Json -InputObject ([IO.File]::ReadAllText((Join-Path $OutDir $File)))
}

# @end
# @helper Read-Lines
# Returns every record in a JSON lines file.
function Read-Lines {
    param([string]$File)
    foreach ($line in [IO.File]::ReadAllLines((Join-Path $OutDir $File))) {
        ConvertFrom-Json -InputObject $line
    }
}

# @end
# @helper Get-Required
# Returns a value the script cannot do without, as a string.
function Get-Required {
    param($Value, [string]$Label)
    if ($null -eq $Value -or "$Value" -eq '') { throw "No value at $Label, so the response has changed." }
    [string]$Value
}

# @end
# @helper Select-Items
# Turns a list that may be missing into an array, without any nulls in it.
function Select-Items {
    param($Value)
    @($Value | Where-Object { $null -ne $_ })
}

# @end
# @helper Add-Lines
# Appends records to a JSON lines file.
function Add-Lines {
    param([string]$Path, $Items)
    foreach ($item in $Items) {
        [IO.File]::AppendAllText($Path, (ConvertTo-Json -InputObject $item -Depth 64 -Compress) + "`n")
    }
}

# @end
# @helper Get-Between
# Cuts a value out of a page using the text around it.
function Get-Between {
    param([string]$Body, [string]$Before, [string]$After)
    $start = $Body.IndexOf($Before, [StringComparison]::Ordinal)
    if ($start -lt 0) { throw "Could not find '$Before' in the response." }
    $start += $Before.Length
    $end = $Body.IndexOf($After, $start, [StringComparison]::Ordinal)
    if ($end -lt 0) { return $Body.Substring($start) }
    $Body.Substring($start, $end - $start)
}

# @end
# @helper Get-UrlParam
# Reads one query parameter from a URL.
function Get-UrlParam {
    param([string]$Url, [string]$Name)
    $match = [regex]::Match($Url, '[?&]' + [regex]::Escape($Name) + '=([^&#]*)')
    if (-not $match.Success) { return '' }
    [uri]::UnescapeDataString($match.Groups[1].Value.Replace('+', ' '))
}

# @end
# @helper Get-JarCookie
# Reads a cookie the server set during this run.
function Get-JarCookie {
    param([string]$Url, [string]$Name)
    $cookie = $Cookies.GetCookies([Uri]$Url)[$Name]
    if ($cookie) { $cookie.Value }
}

# @end
# @helper Format-Form
# Encodes a flat list of names and values as a form body.
function Format-Form {
    param([object[]]$Fields)
    $pairs = for ($index = 0; $index -lt $Fields.Length; $index += 2) {
        '{0}={1}' -f [uri]::EscapeDataString([string]$Fields[$index]), [uri]::EscapeDataString([string]$Fields[$index + 1])
    }
    $pairs -join '&'
}

# @end
{{seed_cookies}}

{{steps}}

[Console]::Error.WriteLine("Done. Responses are in $OutDir")
# @snippet request
{{before}}
$Resp = Send-Request -File {{file}} -Method {{method}} -Url {{url}}{{options}}
# @end
# @snippet extract
${{var}} = {{value}}
# @end
# @snippet counter_loop
${{var}} = {{start}}
$outputFile = {{output}}
[IO.File]::WriteAllText($outputFile, '')
for ($pageNumber = 1; $pageNumber -le {{limit}}; $pageNumber++) {
    {{request}}
# @if capture_first
    if ($pageNumber -eq 1) { $first = $Resp }
# @end
# @if has_items
    $items = @({{items}})
    if ($items.Count -eq 0) { break }
    Add-Lines $outputFile $items
# @end
    ${{var}} += {{step}}
    Start-Sleep -Milliseconds $DelayMs
}
# @end
# @snippet cursor_loop
${{var}} = {{initial}}
$outputFile = {{output}}
[IO.File]::WriteAllText($outputFile, '')
for ($pageNumber = 1; $pageNumber -le $MaxPages; $pageNumber++) {
# @if has_extra_query
    $requestUrl = {{base_url}}
    if (${{var}}) { $requestUrl += {{extra_query}} }
# @end
    {{request}}
# @if capture_first
    if ($pageNumber -eq 1) { $first = $Resp }
# @end
# @if has_items
    Add-Lines $outputFile @({{items}})
# @end
    ${{var}} = {{next_value}}
    if (-not ${{var}}) { break }
    Start-Sleep -Milliseconds $DelayMs
}
# @end
# @snippet next_url_loop
$requestUrl = {{first_url}}
$outputFile = {{output}}
[IO.File]::WriteAllText($outputFile, '')
for ($pageNumber = 1; $pageNumber -le $MaxPages; $pageNumber++) {
    {{request}}
# @if capture_first
    if ($pageNumber -eq 1) { $first = $Resp }
# @end
# @if has_items
    Add-Lines $outputFile @({{items}})
# @end
    $nextValue = {{next_value}}
    if (-not $nextValue) { break }
    $requestUrl = {{next_url}}
    Start-Sleep -Milliseconds $DelayMs
}
# @end
# @snippet foreach_loop
$outputFile = {{output}}
[IO.File]::WriteAllText($outputFile, '')
$pageNumber = 0
foreach (${{var}} in @({{values}} | Select-Object -First $MaxItems)) {
    $pageNumber += 1
    {{request}}
# @if is_json
    Add-Lines $outputFile @(Read-Json $Resp)
# @end
    Start-Sleep -Milliseconds $DelayMs
}
# @end
